source.loginUrl:
function login(){}
function zc() { java.startBrowserAwait("https://api-x.shrtxs.cn/qd/login.php","登录界面")
let data = java.ajax("https://api-x.shrtxs.cn/qd/api_user.php?action=get_my_token");
    let jsonData = JSON.parse(data);
    let token = jsonData.token;
    if (token) {
        java.toast("获取token成功");
        source.put("token", token);
    } else {
        java.toast("获取token失败");
    }
}
function fx(){
	fx = cache.get("fx") !== null && cache.get("fx") !== undefined ? cache.get("fx") : "male";
    if (fx == "male") {
        cache.put("fx", "female");
        java.toast("已切换至女频发现，请刷新");
    } else if (fx == "female") {
        cache.put("fx", "male");
        java.toast("已切换至男频发现，请刷新");
    }
	}

