ruleToc.updateTime:
//h2[@class="book_name"]/a/@title
<js>
var time = /\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}/g.exec(String(result))
var count = /\d{1,5}$/g.exec(String(result))
result = time + "  " + count + " 字"
</js>

